#!/usr/bin/env python3
"""File a safety review report as a byu-vcl issue. No Claude runs in this job.

Run by the `post` job of .github/workflows/safety-review.yml, on a runner that
never held a Claude session, with a token that can write issues and nothing
else. The report is treated as untrusted text, since the session that wrote it
read public comments:

- @mentions are defused (a zero-width space after the @), so the report can't
  notify anyone or contain a live @claude trigger. The issue's assignee is the
  only person notified.
- The body is split under GitHub's 65,536-character limit; overflow goes into
  follow-up comments on the same issue.
- Re-running the job is safe: an issue already carrying this run's marker is
  reused, not duplicated.
- Earlier open reports are closed with a pointer to the new one, since each
  report carries their open items forward.

Uses the gh CLI (preinstalled on GitHub runners) with GH_TOKEN and GH_REPO.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
import sys
import tempfile
from datetime import datetime, timezone
from pathlib import Path

LABEL = "safety-review"
LIMIT = 60_000  # GitHub caps bodies at 65,536; leave room for the header/footer
MENTION = re.compile(r"(?<![\w.`/])@(?=[A-Za-z0-9])")


def gh(*args: str, input_text: str | None = None) -> str:
    return subprocess.run(["gh", *args], check=True, capture_output=True, text=True, input=input_text).stdout.strip()


def body_file(text: str) -> str:
    f = tempfile.NamedTemporaryFile("w", suffix=".md", delete=False, encoding="utf-8")
    f.write(text)
    f.close()
    return f.name


def split(text: str, limit: int) -> list[str]:
    """Split at the last heading (or blank line) before the limit."""
    chunks = []
    while len(text) > limit:
        cut = text.rfind("\n## ", 0, limit)
        if cut < limit // 2:
            cut = text.rfind("\n\n", 0, limit)
        if cut < limit // 2:
            cut = limit
        chunks.append(text[:cut])
        text = text[cut:].lstrip("\n")
    chunks.append(text)
    return chunks


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--report", required=True, type=Path)
    ap.add_argument("--manifest", type=Path)
    ap.add_argument("--assignee", default="")
    args = ap.parse_args()

    repo = os.environ["GH_REPO"]
    run_id = os.environ.get("GITHUB_RUN_ID", "local")
    run_url = f"{os.environ.get('GITHUB_SERVER_URL', 'https://github.com')}/{repo}/actions/runs/{run_id}"
    marker = f"<!-- safety-review-run:{run_id} -->"

    report = args.report.read_text(encoding="utf-8").strip()
    if len(report) < 200:
        print(f"Report is only {len(report)} characters; refusing to post it.", file=sys.stderr)
        return 1
    report = MENTION.sub("@​", report)

    window = ""
    if args.manifest and args.manifest.is_file():
        m = json.loads(args.manifest.read_text(encoding="utf-8"))
        window = f"Window {m['since'][:10]} to {m['until'][:10]}; {m['threads']} active threads read. "
    footer = (
        f"\n\n---\n<sub>{window}Generated by the weekly safety review "
        f"([run]({run_url}), [how it works](https://github.com/{repo}/blob/main/docs/safety-review/README.md)). "
        "An AI-written review: check before acting on it. Reply here with corrections; the next run reads them.</sub>"
    )
    chunks = split(report, LIMIT)
    chunks[0] = marker + "\n" + chunks[0]
    chunks[-1] += footer
    if len(chunks) > 1:
        chunks[0] += f"\n\n_Continued in the {len(chunks) - 1} comment(s) below._"

    gh("label", "create", LABEL, "--color", "B60205", "--force",
       "--description", "Weekly lab safety review (safety-review.yml)")

    existing = json.loads(gh("issue", "list", "--label", LABEL, "--state", "all", "--limit", "20",
                             "--json", "number,body,state"))
    mine = next((i for i in existing if marker in (i.get("body") or "")), None)
    if mine:
        number = mine["number"]
        print(f"Issue #{number} already holds this run's report; not posting again.")
    else:
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        create = ["issue", "create", "--title", f"Lab safety review, {today}",
                  "--label", LABEL, "--body-file", body_file(chunks[0])]
        if args.assignee:
            create += ["--assignee", args.assignee]
        url = gh(*create)
        number = int(url.rstrip("/").rsplit("/", 1)[-1])
        print(f"Created {url}")
        for chunk in chunks[1:]:
            gh("issue", "comment", str(number), "--body-file", body_file(chunk))

    for issue in existing:
        if issue["state"] == "OPEN" and issue["number"] != number:
            gh("issue", "comment", str(issue["number"]), "--body",
               f"Superseded by #{number}, which carries forward this report's open items.")
            gh("issue", "close", str(issue["number"]), "--reason", "completed")
            print(f"Closed #{issue['number']}")

    if summary := os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(summary, "a", encoding="utf-8") as fh:
            fh.write(f"Report filed as #{number}: https://github.com/{repo}/issues/{number}\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
